import cmath
import math


def quotients(f, z, h, n):
    out = []
    for k in range(n):
        d = h * cmath.exp(2j * math.pi * k / n)
        out.append((f(z + d) - f(z)) / d)
    return out


def spread(f, z, h, n):
    q = quotients(f, z, h, n)
    return max(abs(a - b) for a in q for b in q)

